package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLineTest {

    static class TestableCommandLine extends CommandLine {
        String receivedOptionName = null;
        String[] toReturn;
        boolean throwParseException = false;

        TestableCommandLine(String[] toReturn) {
            super();
            this.toReturn = toReturn;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T[] getParsedOptionValues(final String optionName) throws ParseException {
            this.receivedOptionName = optionName;
            if (throwParseException) {
                throw new ParseException("forced parse failure");
            }
            return (T[]) toReturn;
        }
    }

    @Test
    public void returnsArrayAndDelegatesToStringOverload() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(new String[]{"one", "two"});
        // direct invocation of the focal char-based method
        String[] result = cmd.getParsedOptionValues('x');

        assertArrayEquals(new String[]{"one", "two"}, result);
        // verify delegation passed the stringified char
        assertEquals("x", cmd.receivedOptionName);
    }

    @Test
    public void propagatesParseExceptionFromStringOverload() {
        TestableCommandLine cmd = new TestableCommandLine(null);
        cmd.throwParseException = true;

        assertThrows(ParseException.class, () -> cmd.getParsedOptionValues('z'));
    }

    @Test
    public void nullReturnFromStringOverloadIsPreserved() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(null);
        String[] result = cmd.getParsedOptionValues('q');

        assertNull(result);
        assertEquals("q", cmd.receivedOptionName);
    }

    @Test
    public void reflectionInvocationOfCharMethodMatchesDirectCall() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(new String[]{"r"});
        Method m = CommandLine.class.getMethod("getParsedOptionValues", char.class);

        @SuppressWarnings("unchecked")
        String[] viaReflection = (String[]) m.invoke(cmd, 'r');

        String[] direct = cmd.getParsedOptionValues('r');

        assertArrayEquals(direct, viaReflection);
        assertEquals("r", cmd.receivedOptionName);
    }
}

// Minimal ParseException stub so tests compile in this setup.
class ParseException extends Exception {
    private static final long serialVersionUID = 1L;

    public ParseException(String message) {
        super(message);
    }
}

